import sys

data = sys.stdin.read().split()
n = int(data[0])
a = list(map(int, data[1:1 + n]))
cnt = {}
for x in a:
    cnt[x] = cnt.get(x, 0) + 1
best = None
for v, c in cnt.items():
    if best is None or c > best[1] or (c == best[1] and v < best[0]):
        best = (v, c)
print(best[0])

